                    "నీరు H2O: ప్రతి అణువులో ఒక ఆక్సిజన్ పరమాణువుకు రెండు హైడ్రోజన్ పరమాణువులు ఉంటాయి. 2H2O -> 2H2 + O2 కాబట్టి ఆక్సిజన్ కంటే రెండింతలు హైడ్రోజన్ అణువులు ఏర్పడతాయి; అందుకే హైడ్రోజన్ నాళిక రెట్టింపు వేగంతో నిండుతుంది.",
                    "వాయువులను మంటతో పరీక్షించండి. హైడ్రోజన్ 'టప్' అనే శబ్దంతో మండుతుంది. ఆక్సిజన్ స్వయంగా మండదు, కానీ మండుతున్న కొవ్వొత్తి మంటను మరింత ప్రకాశవంతంగా మండేలా చేస్తుంది.",
                    "ఇది వియోగ చర్య: ఒక సంయోగ పదార్థం (నీరు) విద్యుత్ శక్తి సహాయంతో సరళమైన పదార్థాలుగా (హైడ్రోజన్, ఆక్సిజన్) విడిపోతుంది. ఇలాంటి చర్యను విద్యుద్విశ్లేషణ అంటారు.",
                    "సమీకరణం 2H2O -> 2H2 + O2. రెండు నీటి అణువులు విడిపోయి రెండు హైడ్రోజన్ అణువులు, ఒక ఆక్సిజన్ అణువు ఏర్పడతాయి. రెండు వైపులా 4 H, 2 O ఉన్నాయి, కాబట్టి సమతుల్యం.",
                    "కార్బన్ (గ్రాఫైట్) ఎలక్ట్రోడ్లు వాడతారు, ఎందుకంటే కార్బన్ విద్యుత్తును ప్రసారం చేస్తుంది, ఆమ్లం వల్ల గానీ ఏర్పడే వాయువుల వల్ల గానీ అది కరగదు, చర్య జరపదు.",
                    "జాగ్రత్తలు: విలీన సల్ఫ్యూరిక్ ఆమ్లం చర్మానికి, కళ్లకు చికాకు కలిగిస్తుంది కాబట్టి జాగ్రత్తగా వాడండి. 6 వోల్ట్ల విద్యుత్తును నీటి తుంపర్లకు దూరంగా ఉంచండి. మంటను పరీక్ష నాళిక నోటి దగ్గర మాత్రమే ఉంచండి, లోపలికి కాదు.",
                });

            Set(all, MentorKnowledge.Acid, "ద్రావణాలు విద్యుత్తును ప్రసరింపజేస్తాయా?",
                new[] { "ఆమ్లంతో బల్బు ఎందుకు వెలుగుతుంది?", "గ్లూకోజ్తో ఎందుకు వెలగదు?", "అయాన్లు అంటే ఏమిటి?", "పరీక్షల మధ్య బీకరును ఎందుకు ఖాళీ చేయాలి?" },
                new[]
                {
                    "ఆమ్లం నీటిలో కరిగి అయాన్లుగా విడిపోతుంది, ఉదాహరణకు HCl -> H+ + Cl-. ఈ అయాన్లు స్వేచ్ఛగా కదలగలవు; కదిలే అయాన్లు విద్యుత్ ప్రవాహాన్ని వలయం అంతా తీసుకువెళతాయి, అందుకే బల్బు వెలుగుతుంది.",
                    "గ్లూకోజ్, ఆల్కహాల్లలో హైడ్రోజన్ ఉన్నప్పటికీ అవి నీటిలో పూర్తి అణువులుగానే కరుగుతాయి, అయాన్లను ఇవ్వవు. విద్యుత్తును తీసుకువెళ్లడానికి అయాన్లు లేకపోవడంతో బల్బు వెలగదు. కాబట్టి హైడ్రోజన్ ఉన్నంత మాత్రాన ఒక పదార్థం ఆమ్లం కాదు.",
                    "అయాన్లు అంటే విద్యుదావేశం కలిగిన పరమాణువులు లేదా పరమాణు సమూహాలు. ఆమ్ల ద్రావణంలో ధనాత్మక హైడ్రోజన్ అయాన్లు (H+), క్లోరైడ్ (Cl-) వంటి రుణాత్మక అయాన్లు ఉంటాయి. ద్రవంలో అవి కదలగలవు కాబట్టి విద్యుత్తును ప్రసరింపజేస్తాయి.",
                    "ముందు ద్రావణం తరువాతి దానితో కలవకుండా ఉండటానికి పరీక్షల మధ్య బీకరును ఖాళీ చేసి కడుగుతారు. కలిసిపోతే బల్బు ఏ ద్రవం వల్ల వెలిగిందో తెలియక ఫలితం తప్పుదారి పట్టిస్తుంది.",
                    "నీటిలో కరిగినప్పుడు హైడ్రోజన్ అయాన్లను (H+) ఇచ్చే పదార్థం ఆమ్లం. హైడ్రోక్లోరిక్ ఆమ్లం, సల్ఫ్యూరిక్ ఆమ్లం ఇలా చేస్తాయి, కాబట్టి విద్యుత్తును ప్రసరింపజేస్తాయి. హైడ్రోజన్ ఉన్నంత మాత్రాన సరిపోదని ఈ ప్రయోగం చూపుతుంది.",
                    "రెండు మేకులు ఎలక్ట్రోడ్లు: అవి బ్యాటరీ నుండి విద్యుత్తును ద్రావణంలోకి, తిరిగి బయటకు తీసుకువెళతాయి. విద్యుత్ ప్రవహిస్తోందో లేదో బల్బు చూపుతుంది, స్విచ్చు వలయాన్ని మూసివేయడానికి లేదా తెరవడానికి ఉపయోగపడుతుంది.",
                    "హైడ్రోక్లోరిక్ ఆమ్లం: HCl -> H+ + Cl-; సల్ఫ్యూరిక్ ఆమ్లం: H2SO4 -> 2H+ + SO4 (2-). రెండూ నీటిలో హైడ్రోజన్ అయాన్లను విడుదల చేస్తాయి.",
                    "జాగ్రత్తలు: విలీన హైడ్రోక్లోరిక్, సల్ఫ్యూరిక్ ఆమ్లాలు చర్మానికి, కళ్లకు చికాకు కలిగిస్తాయి, కాబట్టి జాగ్రత్తగా వాడండి, తరువాత చేతులు కడుక్కోండి. ఏ ద్రవాన్నీ రుచి చూడకండి.",
                });
        }

        private static void Set(Dictionary<string, MentorExperiment> all, string id, string title, string[] chips, string[] answers)
        {
            MentorExperiment e;
            if (!all.TryGetValue(id, out e)) return;
            e.TitleTe = title;
            e.QuickQuestionsTe = chips;
            for (int i = 0; i < e.Answers.Length && i < answers.Length; i++) e.Answers[i].AnswerTe = answers[i];
        }

        // ---- fixed sentences used around the answers ----
        public const string Greeting = "నమస్కారం! నేను మీ ల్యాబ్ మెంటర్ని. ఈ ప్రయోగం గురించి ఏదైనా అడగండి, లేదా కింది ప్రశ్నలలో ఒకదాన్ని నొక్కండి.";
        public const string Thanks = "మీకు స్వాగతం! ఇంకేదైనా ప్రశ్న ఉంటే అడగండి.";
        public static string Hello(string title, string example) { return "నమస్కారం! నేను మీ ల్యాబ్ మెంటర్ని. " + title + " గురించి ఏదైనా అడగండి, ఉదాహరణకు: " + example; }
        public static string Fallback(string title, string equation, string q1, string q2) { return "నేను " + title + " గురించి సహాయం చేయగలను. ముఖ్యమైన చర్య: " + equation + ".\n\nఇలా అడగండి: " + q1 + " లేదా " + q2; }
    }
}
